<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {createPlatformClient} from '../../../packages/client/src/platform';
import type {Account,RunInfo,PlatformSnapshot,Booking} from '../../../packages/contracts/src/platform';
const api=createPlatformClient('demo'),user=ref<Account|null>(null),username=ref('admin01'),password=ref(''),error=ref(''),busy=ref(false),runs=ref<RunInfo[]>([]),state=ref<PlatformSnapshot|null>(null),scenarios=ref<{id:string;name:string}[]>([]),scenario=ref('weekday'),time=ref(''),connections=ref<any[]>([]),orders=ref<Booking[]>([]),notice=ref(''),demandScale=ref(1),botMax=ref(2),announcementMinutes=ref(10);let stop:(()=>void)|undefined;
let refreshGeneration=0;
async function refresh(){const generation=++refreshGeneration;try{await api.runtime();const [r,s,c,o]=await Promise.all([api.request<{items:RunInfo[]}>('/demo/runs'),api.request<PlatformSnapshot>('/ops/snapshot'),api.request<{items:any[]}>('/demo/connections'),api.request<{items:Booking[]}>('/admin/orders?pageSize=50')]);if(generation!==refreshGeneration||s.run.id!==api.runId)return;error.value="";runs.value=r.items;state.value=s;connections.value=c.items;orders.value=o.items.filter((item:any)=>!item.readonly);}catch(e){if(generation!==refreshGeneration)return;state.value=null;error.value=(e as Error).message;}}
async function login(){busy.value=true;error.value='';try{const result=await api.login(username.value,password.value);if(result.user.role!=='admin'){await api.logout();throw Error('请使用管理员账号');}user.value=result.user;password.value='';await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function action(path:string,input:unknown,confirmText?:string){if(confirmText&&!window.confirm(confirmText))return;busy.value=true;error.value='';notice.value='';try{await api.request(path,'POST',input);await refresh();notice.value='操作已保存，业务端将同步更新。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{const runtime=await api.request<any>('/runtime');scenarios.value=runtime.scenarios;try{user.value=await api.restore();if(user.value)await refresh();}catch{}stop=api.subscribe(()=>{if(user.value&&!busy.value)void refresh();});});onBeforeUnmount(()=>stop?.());
</script>
<template><main><header><div><span class="eyebrow">青岚山境</span><h1>演示控制</h1></div><span v-if="user">{{user.name}}</span></header><p class="error" v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form v-if="!user" class="card login" @submit.prevent="login"><h2>管理员登录</h2><label>账号<input v-model="username" autocomplete="username"></label><label>密码<input v-model="password" type="password" autocomplete="current-password"></label><button :disabled="busy">登录</button></form><template v-else-if="state"><section class="stats"><article><small>当前运行</small><strong>{{state.run.mode==='realtime'?'现场模式':'回放模式'}}</strong><span>{{new Date(state.run.businessTime).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</span></article><article><small>实时在园</small><strong>{{state.public.visitors?.toLocaleString()}}</strong><span>累计入园 {{state.checkedInToday}}</span></article><article><small>停车余位</small><strong>{{state.public.parkingFree}}</strong><span>数据版本 {{state.run.revision}}</span></article></section><div class="grid"><section class="card"><h2>运行与场景</h2><button :disabled="busy" @click="action('/demo/reset',{},'创建此场景的新运行并重置展示？旧运行保留。')">重置当前场景</button><label>预置场景<select v-model="scenario"><option v-for="s in scenarios" :value="s.id">{{s.name}}</option></select></label><div class="actions"><button :disabled="busy" @click="action('/demo/runs',{mode:'replay',scenario},'创建新回放并让业务端切换？原运行会保留。')">创建场景回放</button><button :disabled="busy" @click="action('/demo/runs',{mode:'realtime',scenario:'weekday'},'切换为新的现场运行？')">创建现场运行</button></div><label>切换已有运行<select :value="state.run.id" @change="action('/demo/select',{runId:($event.target as HTMLSelectElement).value},'切换运行后，旧草稿不能提交到新运行。继续？')"><option v-for="r in runs" :value="r.id">{{r.scenario}} · {{r.mode}} · {{r.id.slice(0,8)}}</option></select></label></section><section class="card"><h2>回放时钟</h2><p>新建、切换或重启后的回放停在业务时刻，点击继续后推进；其他运行保留原进度。</p><p v-if="state.run.mode==='realtime'">现场模式跟随上海真实时间。</p><template v-else><p aria-live="polite">{{state.run.paused?'已暂停':'播放中'}} · {{state.run.speed}}×<span v-if="state.run.paused">，点击“继续”开始播放；选择倍速不会自动继续。</span></p><div class="actions"><button :disabled="busy" @click="action('/demo/clock',{paused:!state.run.paused})">{{state.run.paused?'继续':'暂停'}}</button><button v-for="speed in [1,5,30,60,180]" :class="{selected:state.run.speed===speed}" :disabled="busy" @click="action('/demo/clock',{speed})">{{speed}}×</button></div><label>跳转业务时间<input type="datetime-local" v-model="time"></label><button :disabled="busy||!time" @click="action('/demo/clock',{time:time+':00+08:00'},'向后跳时会创建分支并保留原运行。确认跳转？')">跳转</button></template></section><section class="card"><h2>事件控制</h2><div class="actions"><button :disabled="busy" @click="action('/demo/alerts',{})">触发随机现场告警</button><button :disabled="busy" @click="action('/demo/bots',{enabled:true})">开启模拟游客</button><button :disabled="busy" @click="action('/demo/bots',{enabled:false})">暂停模拟游客</button></div><div class="actions"><button :disabled="busy" @click="action('/demo/employees',{enabled:true})">开启模拟员工</button><button :disabled="busy" @click="action('/demo/employees',{enabled:false})">暂停模拟员工</button></div><p>模拟发言最多每分钟两条；模拟员工默认在30—60业务秒内领取，2—5业务分钟后反馈完成；待审批 OA 继续等待人工审批。</p></section><section class="card"><h2>生成参数</h2><label>客流需求系数<input type="number" v-model.number="demandScale" min="0.5" max="1.5" step="0.1"></label><label>模拟发言每分钟上限<input type="number" v-model.number="botMax" min="0" max="2"></label><label>恢复公告保留分钟<input type="number" v-model.number="announcementMinutes" min="1" max="60"></label><button :disabled="busy" @click="action('/demo/config',{demandScale,botMax,announcementMinutes},'保存为新参数版本，仅影响后续生成？')">保存参数版本</button></section><section class="card"><h2>终端连接</h2><ul><li v-for="(c,i) in connections" :key="i">{{c.app}} · {{Date.now()-c.lastSeen<15000?'已连接':'等待心跳'}}</li></ul><p v-if="!connections.length">尚未检测到连接</p></section></div><section class="card"><h2>按订单模拟到离场</h2><button :disabled="busy" @click="action('/demo/seed-orders',{})">补充演示预约</button><div v-if="!orders.length" class="empty">可补充演示预约，或使用游客账号创建预约。</div><div class="order" v-for="o in orders" :key="o.id"><div><strong>{{o.kind==='entry'?'入园预约':'停车预约'}} · {{o.people}}{{o.kind==='entry'?'人':'辆'}}</strong><p>{{o.date}} {{o.slot}} · {{o.userId}} · {{o.entered?(o.exited?'已离场':'已入场'):o.status}}</p></div><div class="actions"><button :disabled="busy||o.entered||o.status!=='confirmed'" @click="action('/demo/orders/'+o.id+'/enter',{expectedVersion:o.version})">模拟入场</button><button :disabled="busy||!o.entered||o.exited" @click="action('/demo/orders/'+o.id+'/exit',{expectedVersion:o.version})">模拟离场</button></div></div></section></template></main></template>
